#!/usr/bin/env python3
"""Build the bilingual bank-statement mortgage product pages from the residential shell."""
from pathlib import Path
import json,re,html
R=Path(__file__).resolve().parent.parent
E=html.escape
states=['Georgia','Alabama','Tennessee','Florida','North Carolina','South Carolina']
copy={
'en':dict(title='Bank Statement Loans for Self-Employed Borrowers',desc='Explore bank statement mortgage options for business owners and self-employed borrowers. Purchase or refinance in GA, AL, TN, FL, NC and SC.',eyebrow='Self-employed mortgage options',h1='Bank statement loans.<br><em>Built around your income.</em>',intro='A bank statement loan may let you document qualifying income through personal or business bank statements. Stonehaven helps self-employed buyers and homeowners compare that path with other mortgage options.',cta='Text me about my options',note='Residential inquiries in GA, AL, TN, FL, NC and SC. Program eligibility varies.',card='What the review considers',facts=[('Income documentation','Personal or business bank statements, as the program permits'),('Statement history','12- or 24-month options may be available'),('Financing goal','Purchase or refinance, subject to program requirements')],fit='Built around how you earn',people=[('Business owners','When your business activity needs a closer look than a single income figure.'),('Independent professionals','Consultants, contractors and other self-employed borrowers with documented deposits.'),('Variable business income','A review of the history and pattern of receipts, including seasonal changes.')],how='How the income review works',steps=[('Start with your situation','Tell us your property state, financing goal and how long you have been self-employed. We follow up by text.'),('Identify the right documentation','A specialist confirms which accounts and statement period the available program needs. Request a secure document link before sending statements.'),('Compare the complete offer','Review qualifying income, credit requirements, down payment or equity, closing costs and monthly payment before deciding how to proceed.')],details='Deposits need context',detailp='A bank statement mortgage still requires documented income and lender underwriting. Transfers between accounts, borrowed funds and other non-income deposits may need to be excluded. Business expenses, ownership share and income trends can affect the result. Total deposits are not automatically your qualifying income.',compare='Compare the income paths',cols=['Question','Conventional review','Bank statement review'],rows=[['Income evidence','Typically uses tax returns and other supporting income records','Uses eligible account activity under the lender’s program rules'],['Self-employment','May qualify under conventional requirements','May provide an alternative documentation path'],['Decision factors','Income, debts, credit, assets and property','Income, debts, credit, assets and property still matter']],tradeoff='Compare both options. Bank statement programs can have different rates, down-payment requirements and fees. A different documentation method does not guarantee a larger loan or a faster closing.',faqtitle='Questions before you start',faqs=[('Does this mean no income verification?','No. Bank statements provide a way to document income. The lender still verifies the file and applies its qualification requirements.'),('Will I need 12 or 24 months of statements?','That depends on the program and your circumstances. Ask which consecutive statements are needed and whether personal or business accounts are appropriate before collecting documents.'),('Can I use this to buy a rental?','Property use affects program eligibility. For an investment property, compare a bank statement review with a DSCR review based on the property’s eligible rental income.'),('What credit score or down payment is required?','Requirements vary with the lender, loan amount, property and overall file. We review those details before presenting an available option.'),('Should I upload my statements here?','No. This is an initial inquiry. Keep account numbers, statements, tax returns and other private documents out of the public form. A specialist can arrange a secure next step.')],formtitle='Start your bank statement loan review',formintro='Share the basics and your mobile number. A Stonehaven specialist will follow up by text.',labels=['Name','Email','Mobile number','Property state','Financing goal','How long have you been self-employed?','Estimated purchase price or property value ($)','Requested loan amount ($)'],goals=['Purchase','Refinance','Cash-out refinance','Exploring'],history=['Less than 1 year','1-2 years','2+ years'],choose='Choose an option',consent='By submitting, you ask Stonehaven Lending to contact you by text or email about this inquiry. Consent is not a condition of service. Message and data rates may apply; reply STOP to opt out.',success='Thank you. We received your inquiry and will follow up by text.',related='Explore related options',links=['Residential home loans','DSCR investor financing','Home equity options'],home='Home'),
'es':dict(title='Préstamos con estados de cuenta para trabajadores independientes',desc='Explore opciones hipotecarias con estados de cuenta para empresarios y trabajadores independientes. Compra o refinanciamiento en GA, AL, TN, FL, NC y SC.',eyebrow='Hipotecas para trabajadores independientes',h1='Préstamos con estados de cuenta.<br><em>Para trabajadores independientes.</em>',intro='Un préstamo con estados de cuenta puede permitir documentar ingresos elegibles mediante cuentas personales o comerciales. Stonehaven ayuda a compradores y propietarios independientes a comparar esta vía con otras opciones hipotecarias.',cta='Quiero recibir un mensaje',note='Consultas residenciales en GA, AL, TN, FL, NC y SC. La elegibilidad varía según el programa.',card='Qué se revisa',facts=[('Documentación de ingresos','Estados personales o comerciales, según el programa'),('Historial de estados','Puede haber opciones de 12 o 24 meses'),('Objetivo','Compra o refinanciamiento, sujeto a requisitos')],fit='Una revisión de cómo genera ingresos',people=[('Dueños de negocios','Cuando la actividad de su empresa necesita una revisión más amplia que una sola cifra de ingresos.'),('Profesionales independientes','Consultores, contratistas y otros trabajadores independientes con depósitos documentados.'),('Ingresos comerciales variables','Revisión del historial y patrón de cobros, incluidos cambios por temporada.')],how='Cómo se revisan los ingresos',steps=[('Explique su situación','Indique estado del inmueble, objetivo y tiempo trabajando por cuenta propia. Le daremos seguimiento por mensaje de texto.'),('Identifique los documentos adecuados','Un especialista confirma las cuentas y el período que requiere el programa. Pida un enlace seguro antes de enviar estados.'),('Compare la oferta completa','Revise ingresos elegibles, crédito, entrada o patrimonio, gastos de cierre y pago mensual antes de decidir cómo continuar.')],details='Los depósitos necesitan contexto',detailp='Una hipoteca con estados de cuenta sigue requiriendo ingresos documentados y evaluación del prestamista. Transferencias entre cuentas, fondos prestados y otros depósitos que no son ingresos pueden excluirse. Los gastos del negocio, porcentaje de propiedad y tendencias pueden afectar el resultado. La suma de depósitos no equivale automáticamente al ingreso elegible.',compare='Compare las vías de documentación',cols=['Pregunta','Revisión convencional','Revisión con estados de cuenta'],rows=[['Evidencia de ingresos','Generalmente utiliza declaraciones fiscales y otros documentos de ingresos','Utiliza actividad elegible de cuentas según las reglas del programa'],['Trabajo independiente','Puede calificar bajo requisitos convencionales','Puede ofrecer otra vía de documentación'],['Factores de decisión','Ingresos, deudas, crédito, activos e inmueble','Ingresos, deudas, crédito, activos e inmueble siguen siendo relevantes']],tradeoff='Compare ambas opciones. Las tasas, entradas y cargos pueden ser distintos. Otra forma de documentar ingresos no garantiza un préstamo mayor ni un cierre más rápido.',faqtitle='Preguntas antes de comenzar',faqs=[('¿Significa que no se verifican ingresos?','No. Los estados de cuenta sirven para documentar ingresos. El prestamista sigue verificando el expediente y aplicando sus requisitos.'),('¿Necesitaré 12 o 24 meses de estados?','Depende del programa y su situación. Pregunte qué estados consecutivos se necesitan y si corresponden cuentas personales o comerciales antes de reunir documentos.'),('¿Puedo utilizarlo para comprar un alquiler?','El uso del inmueble afecta la elegibilidad. Para una inversión, compare esta vía con una revisión DSCR basada en las rentas elegibles del inmueble.'),('¿Qué puntaje o entrada se requiere?','Los requisitos varían con el prestamista, monto, inmueble y expediente. Revisamos esos datos antes de presentar una opción disponible.'),('¿Debo subir mis estados aquí?','No. Es una consulta inicial. No incluya números de cuenta, estados, declaraciones fiscales ni documentos privados en el formulario público. Un especialista puede coordinar el siguiente paso seguro.')],formtitle='Inicie su revisión hipotecaria',formintro='Comparta los datos básicos y su celular. Un especialista de Stonehaven le dará seguimiento por mensaje de texto.',labels=['Nombre','Correo electrónico','Número de celular','Estado del inmueble','Objetivo','¿Cuánto tiempo lleva trabajando por cuenta propia?','Precio de compra o valor estimado ($)','Monto de préstamo solicitado ($)'],goals=['Compra','Refinanciamiento','Refinanciamiento con retiro de efectivo','Explorando'],history=['Menos de 1 año','1-2 años','2 años o más'],choose='Seleccione una opción',consent='Al enviar, solicita que Stonehaven Lending le contacte por mensaje de texto o correo sobre esta consulta. El consentimiento no es condición del servicio. Pueden aplicar tarifas de mensajes y datos; responda STOP para cancelar.',success='Gracias. Recibimos su consulta y le daremos seguimiento por mensaje de texto.',related='Explore otras opciones',links=['Préstamos de vivienda','Financiamiento DSCR para inversionistas','Opciones de patrimonio de vivienda'],home='Inicio')}
for lang,c in copy.items():
 prefix='/es' if lang=='es' else '';url='https://stonehavencre.com'+prefix+'/bank-statement-loans';base=(R/(prefix.lstrip('/')+'/' if prefix else '')/'residential.html').read_text()
 head=base[:base.index('<main>')];footer=base[base.index('</main>')+len('</main>'):]
 head=head.replace('href="/es/residential"','href="/es/bank-statement-loans"') if lang=='en' else head.replace('href="/residential"','href="/bank-statement-loans"')
 if lang=='es': head=head.replace('>Call</a>','>Llamar</a>')
 head=re.sub(r'<title>.*?</title>',f'<title>{E(c["title"])} | Stonehaven</title>',head)
 head=re.sub(r'<meta name="description"[^>]*>',f'<meta name="description" content="{E(c["desc"])}"/>',head)
 for name,value in [('og:title',c['title']),('og:description',c['desc']),('og:url',url)]:head=re.sub(r'<meta property="'+name+r'"[^>]*>',f'<meta property="{name}" content="{E(value)}"/>',head)
 head=re.sub(r'<link rel="canonical"[^>]*>',f'<link rel="canonical" href="{url}"/>',head)
 head=re.sub(r'<link rel="alternate"[^>]*>','',head)
 head=re.sub(r'<script type="application/ld\+json">.*?</script>','',head,flags=re.S)
 schema={'@context':'https://schema.org','@type':'Service','name':c['title'],'serviceType':'Bank statement mortgage brokerage','description':c['desc'],'url':url,'areaServed':[{'@type':'State','name':x} for x in states],'provider':{'@type':'Organization','name':'Stonehaven Lending','url':'https://stonehavencre.com/'}}
 head=head.replace('</head>',f'<link rel="stylesheet" href="/bank-statement.css?v=1"/><link rel="alternate" hreflang="en" href="https://stonehavencre.com/bank-statement-loans"/><link rel="alternate" hreflang="es" href="https://stonehavencre.com/es/bank-statement-loans"/><link rel="alternate" hreflang="x-default" href="https://stonehavencre.com/bank-statement-loans"/><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>')
 def cards(items):return ''.join(f'<div class="bs-card"><h3>{E(h)}</h3><p>{E(p)}</p></div>' for h,p in items)
 hero=f'<section class="bs-hero wrap"><div><nav class="bs-crumb"><a href="{prefix}/">{c["home"]}</a> / <a href="{prefix}/residential">{c["links"][0]}</a></nav><span class="eyebrow">{c["eyebrow"]}</span><h1>{c["h1"]}</h1><p class="bs-intro">{c["intro"]}</p><a class="btn-primary" href="#inquire">{c["cta"]}</a><p class="bs-fine">{c["note"]}</p></div><aside class="bs-summary"><h2>{c["card"]}</h2>'+''.join(f'<div><b>{E(k)}</b><p>{E(v)}</p></div>' for k,v in c['facts'])+'</aside></section>'
 body=f'<section class="wrap bs-section"><h2>{c["fit"]}</h2><div class="bs-grid">{cards(c["people"])}</div></section><section class="bs-tint"><div class="wrap bs-section"><h2>{c["how"]}</h2><div class="bs-grid">{cards(c["steps"])}</div><div class="bs-note"><h3>{c["details"]}</h3><p>{c["detailp"]}</p></div></div></section>'
 body+=f'<section class="wrap bs-section"><h2>{c["compare"]}</h2><div class="bs-table"><table><thead><tr>'+''.join(f'<th scope="col">{E(x)}</th>' for x in c['cols'])+'</tr></thead><tbody>'+''.join('<tr><th scope="row">'+E(row[0])+'</th>'+''.join('<td>'+E(x)+'</td>' for x in row[1:])+'</tr>' for row in c['rows'])+f'</tbody></table></div><p class="bs-fine">{c["tradeoff"]}</p></section>'
 body+=f'<section class="wrap bs-section"><h2>{c["faqtitle"]}</h2>'+''.join(f'<details class="bs-faq"><summary>{E(q)}</summary><p>{E(a)}</p></details>' for q,a in c['faqs'])+'</section>'
 names=['name','email','phone','state','goal','self_employment_history','property_value','requested_amount'];fields=''
 for i,(name,label) in enumerate(zip(names,c['labels'])):
  if i in (3,4,5):
   vals=states if i==3 else c['goals'] if i==4 else c['history'];control=f'<select name="{name}" id="bs-{name}" required><option value="">{c["choose"]}</option>'+''.join(f'<option>{E(x)}</option>' for x in vals)+'</select>'
  else:
   typ=['text','email','tel'][i] if i<3 else 'number';extra=' required' if i<3 else ' min="1" step="0.01"';auto=f' autocomplete="{["name","email","tel"][i]}"' if i<3 else '';control=f'<input id="bs-{name}" name="{name}" type="{typ}"{extra}{auto}/>'
  fields+=f'<div class="lf-field"><label for="bs-{name}">{E(label)}</label>{control}</div>'
 body+=f'<section class="lead" id="inquire"><div class="wrap"><div class="lead-card"><h2>{c["formtitle"]}</h2><p class="sub">{c["formintro"]}</p><form class="lead-form" data-sh-form="residential-bank-statement" data-sh-product="Residential" data-sh-event="lead" data-sh-lang="{lang}" data-sh-about-prefix="Bank statement mortgage inquiry" method="POST" action="{prefix}/bank-statement-loans" data-netlify="true" netlify-honeypot="company_website"><input type="hidden" name="form-name" value="lead"/><input type="hidden" name="loan_program" value="Bank statement mortgage"/><input name="company_website" class="hp-field" tabindex="-1" autocomplete="off" aria-hidden="true"/>{fields}<div class="lead-actions"><span class="note">{c["consent"]} <a href="{prefix}/privacy">'+('Privacidad' if lang=='es' else 'Privacy')+f'</a></span><button class="lead-submit" type="submit">{c["cta"]}</button></div></form><div class="lead-success" role="status"><div class="ok">{c["success"]}</div></div></div></div></section>'
 body+=f'<section class="wrap bs-section"><h2>{c["related"]}</h2><div class="bs-related">'+''.join(f'<a href="{prefix}/{slug}">{label}</a>' for slug,label in zip(['residential','dscr','heloc'],c['links']))+f'</div><p class="bs-fine"><a href="{prefix}/editorial-policy">'+('Criterios editoriales' if lang=='es' else 'Editorial standards')+'</a> · <a href="/management">'+('Nuestro equipo' if lang=='es' else 'Meet the team')+'</a></p></section>'
 footer=footer.replace('href="/es/residential"','href="/es/bank-statement-loans"') if lang=='en' else footer.replace('href="/residential" style="color:var(--stone-400);"','href="/bank-statement-loans" style="color:var(--stone-400);"')
 (R/(prefix.lstrip('/')+'/' if prefix else '')/'bank-statement-loans.html').write_text(head+'<main>'+hero+body+'</main>'+footer)
